return {api_version=1,id="EX1_091",name="Cabal Shadow Priest",text="<b>Battlecry:</b> Take control of an enemy minion that has 2 or less Attack.",set="EXPERT1",type="minion",class="priest",rarity="epic",cost=6,attack=4,health=5,tags={"draenei"},keywords={"battlecry"},target_mode="required_if_available",targets=function(ctx,self)local r={};for _,e in ipairs(ctx:enemy_minions(self))do if ctx:entity(e).attack<=2 then r[#r+1]=e end end;return r end,on_battlecry=function(ctx,self,target)if target then ctx:change_controller(target,ctx:controller(self))end end}
